<script setup lang="ts">
import {Head,Link,useForm} from '@inertiajs/vue3';import {ref} from 'vue';import BusinessFields,{type Field} from '@/components/BusinessFields.vue';
const props=defineProps<{module:string;title:string;record:Record<string,any>;lines:Record<string,any>[];related:Record<string,Record<string,any>[]>;actions:{key:string;label:string;url:string;fields:Field[]}[];attachments?:any[];documentType?:string|null}>();const active=ref<string|null>(null);
const attachment=useForm<{file:File|null;document_type:string|null;document_id:number}>({file:null,document_type:props.documentType??null,document_id:props.record.id});
function defaults(fs:Field[]):Record<string,any>{return Object.fromEntries(fs.map(f=>[f.key,f.type==='repeat'?(Array.isArray(f.default)?structuredClone(f.default):[defaults(f.fields??[])]):f.type==='date'?(f.default||new Date().toISOString().slice(0,10)):(f.default??'')]));}
const forms=Object.fromEntries(props.actions.map(a=>[a.key,useForm<any>({...defaults(a.fields),operation_key:crypto.randomUUID()})]));
function submit(a:any){if(!window.confirm('Konfirmoni këtë veprim? Ai do të regjistrohet në gjurmët e auditimit.'))return;forms[a.key].post(a.url,{preserveScroll:true,onSuccess:()=>{active.value=null;forms[a.key].operation_key=crypto.randomUUID();}});}
const display=(v:any)=>v===null?'—':typeof v==='object'?JSON.stringify(v):String(v);
const keys=(rows:any[])=>rows.length?Object.keys(rows[0]).filter(k=>!['user_id','created_at','updated_at','allocations'].includes(k)):[];
</script>
<template><Head :title="title"/><div class="tp-page-heading"><div><Link :href="'/'+module" class="tp-row-link">← Kthehu te lista</Link><h1>{{title}}</h1></div><a v-if="module==='sales'" :href="`/sales/${record.id}/receipt`" target="_blank" class="tp-button secondary">Dokument i brendshëm</a></div><section class="tp-panel"><dl class="tp-record"><template v-for="(v,k) in record" :key="k"><div v-if="!['user_id','created_at','updated_at'].includes(String(k))"><dt>{{String(k).replaceAll('_',' ')}}</dt><dd>{{display(v)}}</dd></div></template></dl></section>
 <section v-if="module==='products'" class="tp-panel"><a :href="`/products/${record.id}/label`" target="_blank" class="tp-button secondary">Printo etiketën Code 128</a><p class="tp-muted">Caktoni barkodin ASCII; verifikoni printimin me pajisjen fizike.</p></section>
 <section v-if="actions.length" class="tp-panel"><h2>Veprimet e autorizuara</h2><div class="tp-actions"><button v-for="a in actions" :key="a.key" class="tp-button secondary" @click="active=active===a.key?null:a.key">{{a.label}}</button></div><template v-for="a in actions" :key="a.key"><form v-if="active===a.key" class="tp-action-form" @submit.prevent="submit(a)"><h3>{{a.label}}</h3><BusinessFields :fields="a.fields" :model-value="forms[a.key].data()" :errors="forms[a.key].errors" @update:model-value="Object.assign(forms[a.key],$event)"/><p v-for="(e,k) in forms[a.key].errors" :key="k" class="tp-error">{{e}}</p><button class="tp-button" :disabled="forms[a.key].processing">Konfirmo</button></form></template></section>
 <section v-for="[label,rows] in [['Rreshtat',lines],...Object.entries(related)] as [string,Record<string,any>[]][]" :key="label" class="tp-panel"><h2>{{label}}</h2><div v-if="rows.length" class="tp-table-wrap"><table><thead><tr><th v-for="k in keys(rows)" :key="k">{{k.replaceAll('_',' ')}}</th></tr></thead><tbody><tr v-for="(r,i) in rows" :key="i"><td v-for="k in keys(rows)" :key="k">{{display(r[k])}}</td></tr></tbody></table></div><p v-else class="tp-muted">Ende nuk ka regjistra të lidhur.</p></section>
 <section v-if="documentType" class="tp-panel"><h2>Dokumentet mbështetëse</h2><a v-for="a in attachments" :key="a.id" :href="'/documents/'+a.id" class="tp-row-link block mb-3">{{a.original_name}} ↓</a><form v-if="actions.length" @submit.prevent="attachment.post('/documents',{preserveScroll:true})"><label class="tp-field"><span>Faturë ose dokument (PDF / PNG / JPEG, deri në 10 MB)</span><input type="file" accept=".pdf,.png,.jpg,.jpeg" @change="attachment.file=($event.target as HTMLInputElement).files?.[0]??null"/></label><p v-for="(e,k) in attachment.errors" :key="k" class="tp-error">{{e}}</p><button class="tp-button secondary mt-3" :disabled="!attachment.file||attachment.processing">Bashkëngjit dokumentin</button></form></section>
</template>
